	private const string RenaissanceEarlyModernJewelleryDoorsPrerequisiteRerunGuidance =
		"Rerun UsefulSeeder and the item-component seeder until every listed material, tag, and component is available, then rerun Items.";

	private void ValidateRenaissanceEarlyModernJewelleryDoorsPrerequisites()
	{
		var issues = ValidateRenaissanceEarlyModernJewelleryDoorsDependencies(_materials.Keys, _tagsByFullPath.Keys, _components.Keys);
		if (issues.Count > 0)
		{
			throw new InvalidOperationException("Renaissance and Early Modern jewellery and door prerequisites are incomplete; no catalogue item stage has been written." +
				Environment.NewLine + string.Join(Environment.NewLine, issues.Select(x => $" - {x}")) +
				Environment.NewLine + RenaissanceEarlyModernJewelleryDoorsPrerequisiteRerunGuidance);
		}
	}

	private static IReadOnlyList<string> ValidateRenaissanceEarlyModernJewelleryDoorsDependencies(
		IEnumerable<string> materials, IEnumerable<string> tags, IEnumerable<string> components)
	{
		var issues = new List<string>();
		AddMissingRenaissanceEarlyModernJewelleryDoorsDependencies("material", RenaissanceEarlyModernJewelleryDoorsRequiredMaterials, materials, issues);
		AddMissingRenaissanceEarlyModernJewelleryDoorsDependencies("tag", RenaissanceEarlyModernJewelleryDoorsRequiredTags, tags, issues);
		AddMissingRenaissanceEarlyModernJewelleryDoorsDependencies("seeded component", RenaissanceEarlyModernJewelleryDoorsRequiredComponents, components, issues);
		return issues;
	}

	private static void AddMissingRenaissanceEarlyModernJewelleryDoorsDependencies(string dependencyType, IEnumerable<string> required, IEnumerable<string> available, ICollection<string> issues)
	{
		var availableSet = available.ToHashSet(StringComparer.OrdinalIgnoreCase);
		foreach (var name in required.Where(x => !availableSet.Contains(x)))
		{
			issues.Add($"Missing {dependencyType}: {name}");
		}
	}

	internal static IReadOnlyList<string> RenaissanceEarlyModernJewelleryDoorsMaterialsForTesting => RenaissanceEarlyModernJewelleryDoorsRequiredMaterials;
	internal static IReadOnlyList<string> RenaissanceEarlyModernJewelleryDoorsTagsForTesting => RenaissanceEarlyModernJewelleryDoorsRequiredTags;
	internal static IReadOnlyList<string> RenaissanceEarlyModernJewelleryDoorsComponentsForTesting => RenaissanceEarlyModernJewelleryDoorsRequiredComponents;
	internal static IReadOnlyDictionary<string, string> RenaissanceEarlyModernJewelleryDoorsCraftNamesForTesting => RenaissanceEarlyModernJewelleryDoorsCraftNamesByStableReference;
	internal static IReadOnlyList<string> ValidateRenaissanceEarlyModernJewelleryDoorsDependenciesForTesting(IEnumerable<string> materials, IEnumerable<string> tags, IEnumerable<string> components) => ValidateRenaissanceEarlyModernJewelleryDoorsDependencies(materials, tags, components);
